<?php
use App\Models\Quotation; use App\Support\AuthorizationScope;
use function Livewire\Volt\computed; use function Livewire\Volt\layout; use function Livewire\Volt\state;
layout('layouts.app'); state(['status'=>'','source'=>'','search'=>'','customer_id'=>'']);
$quotations=computed(function(){ $u=auth()->user(); $q=Quotation::withoutGlobalScopes()->with(['customer','branch'])->where('company_id',$u->company_id); if(AuthorizationScope::scopeFor($u,'report_scope',AuthorizationScope::BRANCH)!==AuthorizationScope::COMPANY)$q->where('branch_id',$u->branch_id); return $q->when($this->status,fn($x)=>$x->where('status',$this->status))->when($this->source,fn($x)=>$x->where('source_type',$this->source))->when($this->customer_id,fn($x)=>$x->where('customer_id',$this->customer_id))->when($this->search,fn($x)=>$x->where(fn($s)=>$s->where('quotation_number','like',"%{$this->search}%")->orWhereHas('customer',fn($c)=>$c->where('name','like',"%{$this->search}%"))))->latest()->paginate(20); });
?>
